import {createClient} from '@supabase/supabase-js';
import {createDemoStore} from './demo-store.js';
import {createNeonClient} from './neon-client.js';
import {installView,wireInstall} from './install-view.js';
import {definitionEditor,readDefinition,skillBody,wireTree} from './skill-tree.js';
import {treeView,wireWorkspaceTree} from './workspace-tree.js';
import {workspaceSkills} from '../lib/workspace-graph.mjs';
import {formatSkill} from '../lib/skill-format.mjs';

const root=document.querySelector('#root'),modal=document.querySelector('#modal');
const params=new URLSearchParams(location.search);
const state={session:null,data:null,scope:localStorage.getItem('lattice-scope')||'personal',filter:'all',query:'',routeVersion:0};
const demoMode=location.pathname==='/demo';
let client,demoStore,toastTimer,emailAuthReady=true,authProvider='supabase';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=name=>String(name||'You').split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase();
const date=value=>new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value));
const brand='<a class="brand" href="/"><svg class="spark" viewBox="0 0 16 16" aria-hidden="true"><g fill="currentColor"><rect x="2" y="2" width="3" height="3"/><rect x="6.5" y="2" width="3" height="3"/><rect x="2" y="6.5" width="3" height="3"/><rect x="6.5" y="6.5" width="3" height="3"/><rect x="11" y="6.5" width="3" height="3"/><rect x="2" y="11" width="3" height="3"/><rect x="6.5" y="11" width="3" height="3"/><rect x="11" y="11" width="3" height="3"/></g><rect fill="#3e63ff" x="11" y="2" width="3" height="3"/></svg>lattice</a>';
const icons={tree:'⌗',skills:'▦',drafts:'▤',team:'◎',connect:'⌘',settings:'⚙'};
function toast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
function message(error){return error?.message||'Something went wrong. Please try again.';}
function formMessage(form,text,success=false){let box=form.querySelector('[data-message]');if(!box){box=document.createElement('div');box.dataset.message='';box.setAttribute('role','status');form.append(box);}box.className=success?'form-success':'form-error';box.textContent=text;}
async function busy(button,fn){if(button.disabled)return;button.disabled=true;try{await fn();}catch(error){toast(message(error));}finally{if(button.isConnected)button.disabled=false;}}
async function rpc(action,payload={}){if(demoMode)return demoStore.rpc(action,payload);const {data,error}=await client.rpc('lattice_web',{action,payload});if(error)throw error;return data;}
async function refresh(){const userId=state.session?.user.id;const data=await rpc('bootstrap');if(!userId||state.session?.user.id!==userId)return;state.data=data;if(state.scope!=='personal'&&!state.data.teams.some(t=>t.id===state.scope)){state.scope='personal';localStorage.setItem(demoMode?'lattice-demo-scope':'lattice-scope','personal');}}
function go(path){if(demoMode)path=path.replace(/^\/app(?=\?|$)/,'/demo');history.pushState({},'',path);closeModal();route();}
function closeModal(){modal.close();modal.replaceChildren();}
function openModal(title,body){modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${esc(title)}</h2><button class="modal-close" aria-label="Close dialog">×</button></div>${body}`;modal.querySelector('.modal-close').onclick=closeModal;modal.showModal();}
modal.addEventListener('click',event=>{if(event.target===modal){const b=modal.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)closeModal();}});
document.addEventListener('click',event=>{const link=event.target.closest('a[data-route]');if(link&&!event.ctrlKey&&!event.metaKey){event.preventDefault();go(link.getAttribute('href'));}});
window.addEventListener('popstate',route);
let refreshingOnReturn=false;
document.addEventListener('visibilitychange',async()=>{
  if(document.visibilityState!=='visible'||!state.session||!state.data||modal.open||refreshingOnReturn)return;
  refreshingOnReturn=true;
  try{if(authProvider==='neon'){const {data:{session}}=await client.auth.getSession();if(!session||session.user.id!==state.session?.user.id){state.session=session;state.data=null;await route();return;}}await refresh();await route();}catch{toast('Could not refresh your workspace. Try reloading.');}finally{refreshingOnReturn=false;}
});

function authLayout(content){root.innerHTML=`<div class="auth-layout"><aside class="auth-story"><div>${brand}</div><div><div class="auth-chain"><span>▦</span><i>→</i><span>✓</span><i>→</i><span>◎</span></div><p class="eyebrow">YOUR BEST PEOPLE. MULTIPLIED.</p><h1>Good thinking<br>travels.</h1><p>Save the methods that work. Give your teammates and their agents a better place to start.</p></div><p class="auth-foot">ONE PERSON’S KNOW-HOW. A WHOLE TEAM’S ADVANTAGE.</p></aside><main class="auth-main"><div class="auth-box">${content}</div></main></div>`;}
function safeNext(){const query=new URLSearchParams(location.search);const n=query.get('next');return n&&n.startsWith('/')&&!n.startsWith('//')&&!n.includes('\\')?n:'/app';}
function authPage(mode='login'){
  if(authProvider==='neon')return codeAuthPage(mode);
  const signup=mode==='signup',forgot=mode==='forgot',reset=mode==='reset';
  const next=safeNext(),suffix='?next='+encodeURIComponent(next);
  authLayout(`<p class="eyebrow">${signup?'A BETTER WAY TO WORK TOGETHER':'YOUR TEAM’S COLLECTIVE EDGE'}</p><h2>${signup?'Make room for great work.':forgot?'Forgot your password?':reset?'Choose a new password.':'Welcome back.'}</h2><p class="description">${signup?'Create your account. Your first skill starts with the way you already work.':forgot?'We’ll send you a link to reset it.':reset?'Use a unique password with at least 12 characters.':'Pick up where your best thinking left off.'}</p><form id="auth-form">${signup?'<label for="name">Your name</label><input id="name" name="name" autocomplete="name" maxlength="100" required placeholder="Maya Chen">':''}${!reset?'<label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="you@company.com">':''}${!forgot?`<label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${signup||reset?'new-password':'current-password'}" minlength="${signup||reset?'12':'1'}" required placeholder="${signup||reset?'At least 12 characters':'Your password'}">`:''}<button class="button full" type="submit">${signup?'Create account ↗':forgot?'Send reset link ↗':reset?'Update password ↗':'Log in ↗'}</button></form>${!signup&&!forgot&&!reset?`<button class="text-button" id="forgot">Forgot password?</button>`:''}<p class="auth-bottom">${signup?`Already have an account? <a data-route href="/login${suffix}">Log in</a>`:forgot||reset?`<a data-route href="/login${suffix}">Back to log in</a>`:`New to Lattice? <a data-route href="/signup${suffix}">Create an account</a>`}</p>`);
  document.querySelector('#forgot')?.addEventListener('click',()=>authPage('forgot'));
  if(!emailAuthReady&&(signup||forgot)){const form=document.querySelector('#auth-form');formMessage(form,signup?'Registration is opening soon. Please check back shortly.':'Password reset emails are temporarily unavailable. Please try again later.');form.querySelector('button[type=submit]').disabled=true;}
  document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type=submit]');button.disabled=true;try{
    if(!emailAuthReady&&(signup||forgot))throw new Error('Email services are not available yet. Please try again later.');
    const values=Object.fromEntries(new FormData(form));
    if(signup){const {data,error}=await client.auth.signUp({email:values.email,password:values.password,options:{data:{name:values.name.trim()},emailRedirectTo:location.origin+'/app?next='+encodeURIComponent(next)}});if(error)throw error;if(data.session){state.session=data.session;await refresh();go(next);}else{formMessage(form,'Check your email to confirm your account, then log in here. Your invitation will still be waiting.',true);form.querySelector('input[type=password]').value='';}}
    else if(forgot){const {error}=await client.auth.resetPasswordForEmail(values.email,{redirectTo:location.origin+'/app?recovery=1'});if(error)throw error;formMessage(form,'If an account exists for that address, a reset email is on its way.',true);}
    else if(reset){const {error}=await client.auth.updateUser({password:values.password});if(error)throw error;toast('Password updated.');go('/app');}
    else{const {data,error}=await client.auth.signInWithPassword({email:values.email,password:values.password});if(error)throw error;state.session=data.session;await refresh();go(next);}
  }catch(error){formMessage(form,message(error));}finally{button.disabled=false;}};
}

function codeAuthPage(mode='login'){
  const signup=mode==='signup',next=safeNext(),suffix='?next='+encodeURIComponent(next);
  let pending=null,resendAt=0;
  function render(){
    authLayout(`<p class="eyebrow">${pending?'ONE SMALL STEP. THEN YOU’RE IN.':signup?'YOUR TEAM’S NEXT GOOD IDEA STARTS HERE':'YOUR TEAM’S COLLECTIVE EDGE'}</p><h2>${pending?'Check your inbox.':signup?'Make room for great work.':'Welcome back.'}</h2><p class="description">${pending?`Enter the six-digit code sent to <strong>${esc(pending.email)}</strong>. Look for an email from Neon, our sign-in provider.`:'Sign in with a code sent to your email. No password to create or remember.'}</p><form id="code-auth-form">${pending?'<label for="code">Email code</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" minlength="6" required placeholder="000000">':`${signup?'<label for="name">Your name</label><input id="name" name="name" autocomplete="name" maxlength="100" required placeholder="Maya Chen">':''}<label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@company.com">`}<button class="button full" type="submit">${pending?'Verify and continue ↗':'Email me a code ↗'}</button></form>${pending?'<button class="text-button" id="resend-code">Send a new code</button><button class="text-button" id="change-email">Use a different email</button>':`<p class="auth-bottom">${signup?`Already have an account? <a data-route href="/login${suffix}">Log in</a>`:`New to Lattice? <a data-route href="/signup${suffix}">Create an account</a>`}</p>`}<p class="small-note">${pending?'The code can only be used once. Check spam if it hasn’t arrived.':'Your personal skills stay private until you choose to share them.'}</p>`);
    const form=document.querySelector('#code-auth-form');
    form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{
      const values=Object.fromEntries(new FormData(form));
      if(!pending){
        if(!emailAuthReady)throw new Error('Sign-in is opening shortly. Please try again soon.');
        const email=values.email.trim().toLowerCase(),name=values.name?.trim()||email.split('@')[0];
        await client.requestAuth('send',{email});pending={email,name};resendAt=Date.now()+60000;render();document.querySelector('#code')?.focus();
      }else{
        const {session}=await client.requestAuth('verify',{...pending,code:values.code});state.session=session;state.data=null;await refresh();go(next);
      }
    }catch(error){formMessage(form,message(error));}finally{if(button.isConnected)button.disabled=false;}};
    document.querySelector('#change-email')?.addEventListener('click',()=>{pending=null;render();});
    document.querySelector('#resend-code')?.addEventListener('click',event=>busy(event.currentTarget,async()=>{
      if(Date.now()<resendAt){formMessage(form,'Please wait '+Math.ceil((resendAt-Date.now())/1000)+' seconds before requesting another code.');return;}
      await client.requestAuth('send',{email:pending.email});resendAt=Date.now()+60000;formMessage(form,'A new code is on its way. Use the most recent email.',true);
    }));
  }
  render();
}
function codeSettingsPage(){
  shell('settings',`<p class="eyebrow">MAKE YOURSELF AT HOME</p><h1>Your account.</h1><p class="description">Your name travels with the skills you share.</p><div class="panel mt"><form id="profile-form" class="settings-form"><label for="profile-name">Display name</label><input id="profile-name" name="name" value="${esc(state.data.profile.name)}" maxlength="100" required><label for="profile-email">Email address</label><input id="profile-email" value="${esc(state.session.user.email)}" disabled><button class="button" type="submit">Save changes</button></form></div><div class="panel"><h3>Sign in with your email.</h3><p class="description">We send a fresh code each time you log in. There’s no password to remember or reset.</p></div>`);
  document.querySelector('#profile-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;await busy(form.querySelector('button'),async()=>{await rpc('profile',{name:new FormData(form).get('name').trim()});await refresh();codeSettingsPage();toast('Profile updated.');});};
}

function shell(view,content){
  const data=state.data,profile=data.profile,team=data.teams.find(t=>t.id===state.scope);
  const pending=data.skills.filter(s=>s.author_id===profile.id&&s.status==='draft').length;
  root.innerHTML=`<div class="workspace"><aside class="sidebar">${brand}<label class="visually-hidden" for="workspace-picker">Workspace</label><select id="workspace-picker"><option value="personal">⌘ &nbsp; Personal workspace</option>${data.teams.map(t=>`<option value="${t.id}" ${state.scope===t.id?'selected':''}>◎ &nbsp; ${esc(t.name)}</option>`).join('')}</select><nav aria-label="Workspace navigation">${[['tree','Skill tree','/app?view=tree'],['skills','Skill library','/app'],['drafts','Needs approval','/app?view=drafts'],['team','Your teams','/app?view=team'],['connect','Connect your agent','/app?view=connect'],['settings','Settings','/app?view=settings']].map(([id,label,href])=>`<a data-route class="nav-item ${view===id?'active':''}" href="${href}" ${view===id?'aria-current="page"':''}><span>${icons[id]}</span>${label}${id==='drafts'&&pending?`<span class="nav-count">${pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-foot"><div class="user-chip"><span class="avatar">${esc(initials(profile.name))}</span><div><strong>${esc(profile.name)}</strong><small>Your methods, connected.</small></div></div><button class="text-button" data-logout>Log out</button></div></aside><main class="main"><div class="main-top"><span>${team?'◎ '+esc(team.name):'⌘ Personal workspace'} <span class="muted"> / ${view==='connect'?'Connections':view==='team'?'People':view==='settings'?'Account':'Skills'}</span></span><div class="top-actions"><a data-route href="/app?view=connect">${data.connections.filter(c=>new Date(c.expires_at)>new Date()).length?'● Agent connected':'Connect your agent ↗'}</a><button class="text-button" data-logout aria-label="Log out of Lattice">Log out</button></div></div>${content}</main></div>`;
  document.querySelector('#workspace-picker').onchange=event=>{state.scope=event.target.value;localStorage.setItem(demoMode?'lattice-demo-scope':'lattice-scope',state.scope);state.filter='all';if(view==='tree'){go('/app?view=tree&workspace='+encodeURIComponent(state.scope));}else if(new URLSearchParams(location.search).has('skill')){go('/app');}else{const u=new URL(location.href);u.searchParams.delete('workspace');history.replaceState({},'',u);route();}};
  document.querySelectorAll('[data-logout]').forEach(button=>{if(demoMode){button.textContent='Back to website';button.setAttribute('aria-label','Back to website');button.onclick=()=>location.assign('/');}else button.onclick=async()=>{await client.auth.signOut();state.session=null;state.data=null;go('/login');};});
  if(demoMode){document.querySelectorAll('a[data-route]').forEach(a=>a.setAttribute('href',a.getAttribute('href').replace(/^\/app(?=\?|$)/,'/demo')));const banner=document.createElement('div');banner.className='demo-banner';banner.innerHTML='<span><strong>Demo workspace</strong> · Saved in this browser. Team activity is simulated.</span><button class="text-button" id="reset-demo">Reset demo ↺</button>';document.querySelector('.main-top').after(banner);document.querySelector('#reset-demo').onclick=()=>confirmAction('Start fresh?','This resets only the demo skills and teams saved in this browser.','Reset demo',async()=>{demoStore.reset();state.scope=demoStore.defaultTeam;localStorage.setItem('lattice-demo-scope',state.scope);state.query='';await refresh();go('/app');});document.querySelector('.top-actions a').textContent='Try the Codex flow ↗';const onboarding=document.querySelector('.onboard');if(onboarding){onboarding.querySelector('p').textContent='Try capturing, approving, and sharing a method in an example conversation.';onboarding.querySelector('a').textContent='Try the flow ↗';}}
}

function workspaceTreePage(){
  const base=demoMode?'/demo':'/app';
  const view=treeView(state.data,state.scope,base);
  shell('tree',view.html);
  wireWorkspaceTree(document.querySelector('.atlas'),{...view,scope:state.scope,base,rpc,onCreate:()=>skillEditor()});
}
function library(drafts=false){
  const own=state.data.profile.id;
  let skills=state.data.skills.filter(s=>drafts?s.author_id===own&&s.status==='draft':s.status==='approved'&&(state.scope==='personal'?!s.team_id&&s.author_id===own:s.team_id===state.scope));
  if(state.filter==='mine')skills=skills.filter(s=>s.author_id===own);
  if(state.query)skills=skills.filter(s=>(s.title+' '+s.description+' '+s.category+' '+s.author_name).toLowerCase().includes(state.query.toLowerCase()));
  const cards=skills.map(s=>`<article class="skill-card"><div class="card-top"><span class="category">${esc(s.category.toUpperCase())}</span><span class="badge ${s.status==='draft'?'draft':''}">${s.status==='draft'?'AWAITING YOUR YES':s.team_id?'↗ TEAM SKILL':'◎ PRIVATE'}</span></div><h3><a data-route href="/app?skill=${s.id}">${esc(s.title)}</a></h3><p>${esc(s.description||s.method)}</p><div class="card-foot"><span class="card-author"><span class="avatar">${esc(initials(s.author_name))}</span>${esc(s.author_name)}</span><a data-route class="card-open" href="/app?skill=${s.id}" aria-label="Open ${esc(s.title)}">↗</a></div></article>`).join('');
  shell(drafts?'drafts':'skills',`<div class="title-row"><div><p class="eyebrow">${drafts?'YOUR JUDGMENT MAKES IT A SKILL':'GREAT THINKING. READY TO BORROW.'}</p><h1>${drafts?'Is this the ideal way?':'The way we do great work.'}</h1><p class="description">${drafts?'Review the methods your agent captured. Nothing is shared until you say yes.':state.scope==='personal'?'Your approved methods, saved in one place. Share them when you’re ready.':'The methods your team stands behind. Borrow one and make your next task better.'}</p></div><button class="button" id="new-skill">+ New skill</button></div><div class="toolbar"><div class="filters"><button class="filter ${state.filter==='all'?'active':''}" data-filter="all">${drafts?'All drafts':'All skills'} · ${skills.length}</button>${!drafts&&state.scope!=='personal'?`<button class="filter ${state.filter==='mine'?'active':''}" data-filter="mine">Created by me</button>`:''}</div><label class="visually-hidden" for="search">Search skills</label><input class="search" id="search" placeholder="Search your team’s thinking…" value="${esc(state.query)}"></div>${cards?`<div class="skill-grid">${cards}</div>`:`<div class="empty"><span class="spark">▦</span><h2>${state.query?'No matching skills.':drafts?'No methods waiting on you.':'Your best method belongs here.'}</h2><p>${state.query?'Try a different title, author, or category.':drafts?'Ask your agent to capture a method, or create your first skill here.':'Connect your agent and say “this is the ideal way—save it as a Lattice skill.” Or add a method yourself.'}</p><div class="empty-actions"><a class="button" data-route href="/app?view=connect">Connect your agent ↗</a><button class="button secondary" id="empty-create">Create a skill</button></div></div>`}${!state.data.connections.length&&!drafts?'<div class="onboard"><div><h3>Your next skill is already in your workflow.</h3><p>Connect Lattice to your agent. Capture the thinking behind the work, right in your conversation.</p></div><a data-route class="button" href="/app?view=connect">Set up in two minutes ↗</a></div>':''}`);
  document.querySelector('#new-skill').onclick=()=>skillEditor();document.querySelector('#empty-create')?.addEventListener('click',()=>skillEditor());
  document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{state.filter=button.dataset.filter;library(drafts);});
  document.querySelector('#search').oninput=event=>{const position=event.target.selectionStart;state.query=event.target.value;library(drafts);const input=document.querySelector('#search');input.focus();input.setSelectionRange(position,position);};
}
function skillEditor(skill){
  openModal(skill?'Refine the method':'Capture a method',`<p class="modal-description">${skill?'Editing returns this skill to a private draft. Approve the updated method before your team borrows it again.':'Describe the approach, not just the result. Save a private draft first, then review it.'}</p><form id="skill-form"><label for="skill-title">Skill name</label><input id="skill-title" name="title" value="${esc(skill?.title)}" maxlength="120" required placeholder="Design a clear, consistent page"><div class="form-grid"><div><label for="skill-category">Category</label><select id="skill-category" name="category">${['Design','Engineering','Writing','Research','Product','Other'].map(c=>`<option ${skill?.category===c?'selected':''}>${c}</option>`).join('')}</select></div></div><label for="skill-description">When to use it</label><input id="skill-description" name="description" maxlength="600" value="${esc(skill?.description)}" placeholder="Use when building a new page in our product."><label for="skill-method">The method</label><textarea id="skill-method" name="method" rows="8" maxlength="20000" required placeholder="1. Start with the primary action…">${esc(skill?.method)}</textarea>${definitionEditor(skill,workspaceSkills(state.data.skills,state.scope,state.data.profile.id))}<div class="modal-actions"><button type="button" class="button ghost" data-cancel>Cancel</button><button class="button" type="submit">Save private draft ↗</button></div></form>`);
  modal.querySelector('[data-cancel]').onclick=closeModal;
  modal.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(form));payload.definition=readDefinition(form);if(skill)payload.id=skill.id;const saved=await rpc(skill?'skill_update':'skill_create',payload);closeModal();await refresh();go('/app?skill='+saved.id);toast('Private draft saved.');}catch(error){formMessage(form,message(error));}finally{button.disabled=false;}};
}
function teamOptions(selected){return `<option value="">Keep in my account</option>${state.data.teams.map(t=>`<option value="${t.id}" ${selected===t.id?'selected':''}>Share with ${esc(t.name)}</option>`).join('')}`;}
async function skillDetail(id){
  const routeVersion=state.routeVersion;
  const current=state.data.skills.find(s=>s.id===id);
  if(!current){shell('skills','<div class="empty"><h2>This skill isn’t available.</h2><p>It may have been archived, or you may no longer have access.</p><a data-route class="button" href="/app">Back to library</a></div>');return;}
  let skill;
  try{const wanted=Number(new URLSearchParams(location.search).get('version'))||undefined;skill=await rpc('skill_inspect',{id,...(wanted?{version:wanted}:{})});}catch(error){shell('skills','<p class="form-error">'+esc(message(error))+'</p>');return;}
  if(routeVersion!==state.routeVersion)return;
  const own=skill.author_id===state.data.profile.id,draft=skill.status==='draft',historical=skill.version!==current.version;
  shell(draft?'drafts':'skills',`<a data-route class="back-link" href="/app${draft?'?view=drafts':''}">← Back to ${draft?'drafts':'library'}</a><p class="eyebrow">${esc(skill.category.toUpperCase())} / VERSION ${skill.version}</p><h1>${esc(skill.title)}</h1><p class="description">${esc(skill.description)}</p><div class="detail-meta"><span>Method by ${esc(skill.author_name)}</span><span>· ${skill.source==='web'?'Created in Lattice':'Captured in '+esc(({codex:'Codex',claude:'Claude',cursor:'Cursor',mcp:'an MCP agent'})[skill.source]||'an agent')}</span><span class="badge ${draft?'draft':''}">${draft?'PRIVATE DRAFT':skill.team_name?'SHARED WITH '+esc(skill.team_name.toUpperCase()):'PERSONAL SKILL'}</span></div>${historical?'<p class="banner">You’re viewing pinned version '+skill.version+'. <a data-route href="/app?skill='+id+'">Open the latest version</a></p>':''}<section id="skill-body">${skillBody(skill)}</section>${own&&draft?`<div class="approval-panel"><h3>Is this the ideal way to do it?</h3><p>Review the method and its child skills. To share this tree, every child must also be shared with the same team.</p><label for="approval-team">Who can borrow it?</label><select id="approval-team">${teamOptions(state.scope==='personal'?'':state.scope)}</select><button class="button" id="approve">Yes, approve this method ↗</button></div>`:''}<div class="detail-actions">${!draft?'<button class="button" id="borrow">Borrow this skill ↗</button><button class="button secondary" id="download-skill">Download SKILL.md ↓</button>':''}${own&&!historical?`<button class="button secondary" id="edit-skill">Edit method</button>${!draft?'<button class="button ghost" id="share-skill">Manage sharing</button>':''}<button class="button ghost" id="archive-skill">Archive</button>`:''}</div>${!draft?'<section class="panel mt"><h3>Your recent method loads</h3><p class="small-note">Records which versions you or your agent loaded. Loading a method does not prove its steps were completed.</p><div id="skill-usage"><p class="small-note">Loading history…</p></div></section>':''}`);
  wireTree(document.querySelector('#skill-body'),rpc);
  document.querySelector('#approve')?.addEventListener('click',event=>busy(event.currentTarget,async()=>{await rpc('skill_approve',{id,team_id:document.querySelector('#approval-team').value});await refresh();await skillDetail(id);toast('Approved. Your skill is ready to borrow.');}));
  document.querySelector('#edit-skill')?.addEventListener('click',()=>skillEditor(current));
  const loaded=()=>rpc('skill_borrow',{id,version:skill.version});
  document.querySelector('#borrow')?.addEventListener('click',event=>busy(event.currentTarget,async()=>{const saved=await loaded();await copyText(formatSkill(saved),true);toast('Method copied, including pinned child references.');showUsage();}));
  document.querySelector('#download-skill')?.addEventListener('click',event=>busy(event.currentTarget,async()=>{const saved=await loaded();const name=saved.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,64)||'team-method';download('SKILL.md','---\nname: '+name+'\ndescription: '+JSON.stringify(saved.description||'Apply this approved method.')+'\n---\n\n'+formatSkill(saved));showUsage();}));
  document.querySelector('#share-skill')?.addEventListener('click',()=>{openModal('Choose who can borrow it',`<p class="modal-description">Share children with the same team first. Pinned versions keep their content; access follows each skill’s current visibility.</p><label for="share-team">Visibility</label><select id="share-team">${teamOptions(skill.team_id)}</select><div class="modal-actions"><button class="button" id="save-sharing">Save sharing</button></div>`);document.querySelector('#save-sharing').onclick=event=>busy(event.currentTarget,async()=>{await rpc('skill_share',{id,team_id:document.querySelector('#share-team').value});closeModal();await refresh();await skillDetail(id);toast('Sharing updated.');});});
  document.querySelector('#archive-skill')?.addEventListener('click',()=>confirmAction('Archive this skill?','It will leave your library. Trees that depend on it will show an unavailable step.','Archive skill',async()=>{await rpc('skill_archive',{id});await refresh();go('/app');}));
  async function showUsage(){try{const rows=await rpc('skill_usage',{id});const target=document.querySelector('#skill-usage');if(routeVersion!==state.routeVersion||!target)return;target.innerHTML=rows.length?rows.map(row=>'<p class="usage-row">'+esc(state.data.skills.find(s=>s.id===row.skill_id)?.title||'Method')+' · v'+(row.skill_version||'—')+(row.parent_skill_id?' · child of v'+row.parent_version:'')+'<small>'+date(row.created_at)+'</small></p>').join(''):'<p class="small-note">No method loads recorded yet.</p>';}catch{const target=document.querySelector('#skill-usage');if(target)target.textContent='Could not load history.';}}
  if(!draft)showUsage();
}
function confirmAction(title,description,label,fn){openModal(title,`<p class="modal-description">${esc(description)}</p><div class="modal-actions"><button class="button ghost" data-cancel>Cancel</button><button class="button danger" id="confirm-action">${esc(label)}</button></div>`);modal.querySelector('[data-cancel]').onclick=closeModal;document.querySelector('#confirm-action').onclick=event=>busy(event.currentTarget,async()=>{await fn();closeModal();});}
function createTeam(){openModal('Make space for your team',`<p class="modal-description">Bring your people’s best methods into one shared library.</p><form id="team-form"><label for="team-name">Team name</label><input name="name" id="team-name" maxlength="100" required placeholder="Acme Design"><div class="modal-actions"><button class="button" type="submit">Create team ↗</button></div></form>`);modal.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{const saved=await rpc('team_create',{name:new FormData(form).get('name').trim()});state.scope=saved.id;localStorage.setItem(demoMode?'lattice-demo-scope':'lattice-scope',saved.id);closeModal();await refresh();go('/app?view=team');toast('Your team is ready. Invite someone to join.');}catch(error){formMessage(form,message(error));}};}
async function teamsPage(version){
  const teams=state.data.teams,team=teams.find(t=>t.id===state.scope)||teams[0];
  shell('team',`<div class="title-row"><div><p class="eyebrow">MANY MINDS. SHARED METHODS.</p><h1>Your people, connected.</h1><p class="description">Create a team or invite a teammate. Their next great method could be your new favorite skill.</p></div><button class="button" id="create-team">+ New team</button></div>${!teams.length?'<div class="empty"><span class="spark">◎</span><h2>Great work starts with good people.</h2><p>Create your first team. To join someone else’s team, open their invitation link.</p><button class="button" id="first-team">Create a team ↗</button></div>':`<div class="filters mt">${teams.map(t=>`<button class="filter ${t.id===team.id?'active':''}" data-team="${t.id}">${esc(t.name)}</button>`).join('')}</div><div id="team-content" class="mt"><p class="inline-loading">Loading your team…</p></div>`}`);
  document.querySelector('#create-team').onclick=createTeam;document.querySelector('#first-team')?.addEventListener('click',createTeam);
  document.querySelectorAll('[data-team]').forEach(button=>button.onclick=()=>{state.scope=button.dataset.team;localStorage.setItem(demoMode?'lattice-demo-scope':'lattice-scope',state.scope);route();});
  if(!team)return;
  try{const details=await rpc('team_details',{id:team.id});if(version!==state.routeVersion)return;
    document.querySelector('#team-content').innerHTML=`<div class="panel"><div class="panel-heading"><h3>${esc(team.name)} <span class="badge">${details.members.length} ${details.members.length===1?'MEMBER':'MEMBERS'}</span></h3>${team.role==='owner'?'<button class="button secondary" id="invite">Invite a teammate ↗</button>':'<button class="button ghost" id="leave-team">Leave team</button>'}</div>${details.members.map(m=>`<div class="member-row"><div class="row-person"><span class="avatar">${esc(initials(m.name))}</span><div><strong>${esc(m.name)}${m.id===state.data.profile.id?' (you)':''}</strong><small>Joined ${date(m.joined_at)}</small></div></div><div class="row-actions"><span class="badge">${m.role.toUpperCase()}</span>${team.role==='owner'&&m.role!=='owner'?`<button class="text-button" data-remove="${m.id}">Remove</button>`:''}</div></div>`).join('')}</div>${team.role==='owner'?`<div class="panel"><div class="panel-heading"><h3>Pending invitations</h3><span class="badge">EXPIRE AFTER 7 DAYS</span></div>${details.invites.length?details.invites.map(i=>`<div class="invite-row"><div class="row-person"><div><strong>${esc(i.email||'One-time invitation link')}</strong><small>Expires ${date(i.expires_at)}</small></div></div><button class="text-button" data-revoke-invite="${i.id}">Revoke</button></div>`).join(''):'<p class="small-note">No pending invitations. Invite links are single-use and can be revoked anytime.</p>'}</div>`:''}`;
    document.querySelector('#invite')?.addEventListener('click',()=>inviteTeam(team));
    document.querySelector('#leave-team')?.addEventListener('click',()=>confirmAction('Leave '+team.name+'?','You’ll lose access to the team library. Your own skills will return to your personal workspace.','Leave team',async()=>{await rpc('team_leave',{team_id:team.id});await refresh();route();}));
    document.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>confirmAction('Remove this teammate?','They will lose access to this team’s library. Their authored skills return to their personal workspace.','Remove teammate',async()=>{await rpc('member_remove',{team_id:team.id,user_id:button.dataset.remove});await refresh();route();}));
    document.querySelectorAll('[data-revoke-invite]').forEach(button=>button.onclick=()=>confirmAction('Revoke this invitation?','Anyone holding this link will no longer be able to join.','Revoke invitation',async()=>{await rpc('invite_revoke',{id:button.dataset.revokeInvite});route();}));
  }catch(error){if(version===state.routeVersion)document.querySelector('#team-content').innerHTML=`<div class="form-error">${esc(message(error))}</div>`;}
}
function inviteTeam(team){if(demoMode)return demoInviteTeam(team);openModal('Invite someone to '+team.name,`<p class="modal-description">Create a one-time link. Your teammate can sign up or log in, then join your organization. Copy the link and send it yourself.</p><form id="invite-form"><label for="invite-email">Restrict to an email address <span class="muted">(optional)</span></label><input type="email" name="email" id="invite-email" placeholder="teammate@company.com"><p class="small-note">Without an email restriction, anyone with the link can accept it once. The link expires in 7 days.</p><div class="modal-actions"><button class="button" type="submit">Create invite link ↗</button></div></form>`);modal.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{const invite=await rpc('invite_create',{team_id:team.id,email:new FormData(form).get('email')});const url=location.origin+'/join?token='+invite.token;openModal('Your teammate’s way in',`<p class="modal-description">Share this link with your teammate. It can be used once and expires in 7 days.</p><div class="invite-link">${esc(url)}</div><div class="modal-actions"><button class="button" id="copy-invite">Copy invite link ↗</button></div>`);document.querySelector('#copy-invite').onclick=()=>copyText(url);route();}catch(error){formMessage(form,message(error));button.disabled=false;}};}
function codeBlock(code,id){return `<div class="code-block"><pre id="${id}">${esc(code)}</pre><button class="copy-button" data-copy="${id}">Copy</button></div>`;}
function connectPage(){
  if(demoMode)return demoCodexPage();
  const endpoint=location.origin+'/mcp';
  shell('connect',installView()+`<div class="panel"><div class="panel-heading"><h3>Your connected agents</h3><button class="text-button" id="refresh-connections">Refresh</button></div>${state.data.connections.length?state.data.connections.map(c=>`<div class="connection-row"><div class="row-person"><span class="avatar">⌘</span><div><strong>${esc(c.name)}</strong><small>${c.last_used_at?'Last used '+date(c.last_used_at):'Not used yet'} · ${new Date(c.expires_at)>new Date()?'Expires '+date(c.expires_at):'Access token expired'}</small></div></div><button class="button ghost" data-revoke-connection="${c.id}">Disconnect</button></div>`).join(''):'<p class="small-note">No agents connected yet. Complete sign-in, then refresh.</p>'}<button class="text-button" id="manual-token">Advanced: create a Codex access token</button></div>`);
  wireInstall();
  document.querySelectorAll('[data-copy]').forEach(button=>button.onclick=()=>copyText(document.getElementById(button.dataset.copy).textContent));
  document.querySelector('#refresh-connections').onclick=event=>busy(event.currentTarget,async()=>{await refresh();connectPage();});
  document.querySelector('#manual-token').onclick=()=>{openModal('Create a Codex access token',`<p class="modal-description">This token lets Codex read available skills and propose private drafts in your account. It expires after 90 days and can be revoked here.</p><form id="token-form"><label for="connection-name">Connection name</label><input id="connection-name" name="name" maxlength="100" value="Codex on my computer" required><div class="modal-actions"><button class="button" type="submit">Create token</button></div></form>`);modal.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{const c=await rpc('connection_create',{name:new FormData(form).get('name')});openModal('Save your token somewhere safe',`<p class="modal-description">Shown only once. Keep it out of chats, repositories, and screenshots.</p><label for="new-token">Access token</label><input id="new-token" type="password" readonly value="${esc(c.token)}"><div class="modal-actions"><button class="button" id="copy-token">Copy token</button></div><p class="small-note">Store it in a local environment variable named LATTICE_ACCESS_TOKEN, then add the server with:</p>${codeBlock('codex mcp add lattice --url '+endpoint+' --bearer-token-env-var LATTICE_ACCESS_TOKEN','token-command')}`);document.querySelector('#copy-token').onclick=()=>copyText(c.token);document.querySelector('[data-copy]').onclick=()=>copyText(document.querySelector('#token-command').textContent);await refresh();connectPage();}catch(error){formMessage(form,message(error));}};};
  document.querySelectorAll('[data-revoke-connection]').forEach(button=>button.onclick=()=>confirmAction('Disconnect this agent?','Its access and refresh tokens will stop working immediately. You can connect again later.','Disconnect',async()=>{await rpc('connection_revoke',{id:button.dataset.revokeConnection});await refresh();connectPage();}));
}
function settingsPage(){if(demoMode)return demoSettingsPage();if(authProvider==='neon')return codeSettingsPage();shell('settings',`<p class="eyebrow">MAKE YOURSELF AT HOME</p><h1>Your account.</h1><p class="description">Your name travels with the skills you share.</p><div class="panel mt"><form id="profile-form" class="settings-form"><label for="profile-name">Display name</label><input id="profile-name" name="name" value="${esc(state.data.profile.name)}" maxlength="100" required><label for="profile-email">Email address</label><input id="profile-email" value="${esc(state.session.user.email)}" disabled><button class="button" type="submit">Save changes</button></form></div><div class="panel"><h3>Password</h3><p class="description">Send a secure reset link to your account’s email address.</p><button class="button secondary mt" id="reset-email">Send password reset email</button></div>`);document.querySelector('#profile-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{await rpc('profile',{name:new FormData(form).get('name').trim()});await refresh();settingsPage();toast('Profile updated.');}catch(error){formMessage(form,message(error));}};document.querySelector('#reset-email').onclick=event=>busy(event.currentTarget,async()=>{const {error}=await client.auth.resetPasswordForEmail(state.session.user.email,{redirectTo:location.origin+'/app?recovery=1'});if(error)throw error;toast('Check your inbox for the reset link.');});}
async function joinPage(){const token=new URLSearchParams(location.search).get('token');root.innerHTML=`<div class="center-page">${brand}<div class="join-card"><p class="eyebrow">GREAT WORK IS BETTER TOGETHER</p><h1>A place on the team.</h1><p class="description" id="join-description">Checking your invitation…</p><div id="join-action"></div></div></div>`;try{if(!token)throw new Error('This invitation link is incomplete.');const invite=await rpc('invite_preview',{token});document.querySelector('#join-description').textContent='You’ve been invited to '+invite.team_name+'. Join to browse and borrow the team’s approved skills, and share your own.';document.querySelector('#join-action').innerHTML='<button class="button" id="accept-invite">Join team ↗</button>';document.querySelector('#accept-invite').onclick=event=>busy(event.currentTarget,async()=>{await rpc('invite_accept',{token});state.scope=invite.team_id;localStorage.setItem(demoMode?'lattice-demo-scope':'lattice-scope',invite.team_id);await refresh();go('/app');toast('Welcome to '+invite.team_name+'.');});}catch(error){document.querySelector('#join-description').textContent=message(error);document.querySelector('#join-action').innerHTML='<a class="button secondary" data-route href="/app">Go to my workspace</a>';}}
async function authorizePage(){root.innerHTML=`<div class="center-page">${brand}<div class="authorize-card"><p class="eyebrow">CONNECT YOUR CODING AGENT</p><h1>Your skills. In your agent.</h1><p class="description" id="authorize-description">Checking the connection request…</p><div id="authorize-content"></div></div></div>`;try{const response=await fetch('/api/oauth?action=inspect&'+new URLSearchParams(location.search));const info=await response.json();if(!response.ok)throw new Error(info.error_description||'This connection request is invalid.');document.querySelector('#authorize-description').textContent=info.client_name+' wants to connect to your Lattice account ('+state.session.user.email+').';document.querySelector('#authorize-content').innerHTML='<ul class="permission-list"><li>Read and borrow skills available to your account.</li><li>Capture private drafts from work you share with it.</li><li>Save and share a method when you approve its card.</li></ul><p class="small-note">Your password is never shared with the agent. Disconnect it anytime in Lattice.</p><button class="button full" id="allow-connection">Authorize connection ↗</button><button class="text-button" id="deny-connection">Cancel</button>';document.querySelector('#deny-connection').onclick=()=>go('/app?view=connect');document.querySelector('#allow-connection').onclick=event=>busy(event.currentTarget,async()=>{const {data:{session}}=await client.auth.getSession();const r=await fetch('/api/oauth?action=authorize',{method:'POST',headers:{'Content-Type':'application/json',...(session.access_token?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify(Object.fromEntries(new URLSearchParams(location.search)))});const body=await r.json();if(!r.ok)throw new Error(body.error_description||'Could not authorize this connection.');location.assign(body.redirect);});}catch(error){document.querySelector('#authorize-description').textContent=message(error);}}
async function copyText(text,quiet=false){try{await navigator.clipboard.writeText(text);if(!quiet)toast('Copied.');}catch{openModal('Copy this text',`<textarea rows="7" readonly id="copy-fallback">${esc(text)}</textarea>`);modal.querySelector('textarea').select();if(quiet)throw new Error('Clipboard unavailable. Copy the selected text manually.');}}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function demoCodexPage(){
  const captured=state.data.skills.find(s=>s.id===new URLSearchParams(location.search).get('capture'));
  shell('connect',`<p class="eyebrow">FROM ONE GOOD TASK TO EVERYONE’S NEXT ONE</p><h1>That’s the way. Save it.</h1><p class="description">Try the flow with an example conversation. Capture a method, give it your yes, and choose a team.</p><div class="demo-flow"><div class="demo-chat"><div class="demo-chat-heading"><span>⌘ Codex conversation</span><span class="badge">INTERACTIVE PREVIEW</span></div><div class="demo-message"><span class="avatar">${esc(initials(state.data.profile.name))}</span><div><strong>You</strong><p>This is the ideal way to build the page. Save the approach so everyone can use it.</p></div></div><div class="demo-message"><span class="avatar">▦</span><div><strong>Agent</strong><p>I’ll capture the method behind the work. You can review it before it becomes a shared skill.</p></div></div>${!captured?`<form id="demo-capture-form" class="demo-capture"><label for="capture-title">Skill name</label><input id="capture-title" name="title" maxlength="120" required value="Design around one clear action"><label for="capture-method">The reusable method</label><textarea id="capture-method" name="method" rows="6" maxlength="20000" required>1. Name the one action the page should make effortless.
2. Build the hierarchy around that action.
3. Reuse the team’s components and spacing.
4. Check the layout on a small screen.
5. Remove anything that competes for attention.</textarea><button class="button mt" type="submit">Capture this method ↗</button></form>`:`<div class="demo-approval"><p class="eyebrow">${captured.status==='draft'?'READY FOR YOUR JUDGMENT':'✓ METHOD SAVED'}</p><h2>${esc(captured.title)}</h2><div class="activity-method">${esc(captured.method)}</div>${captured.status==='draft'?`<h3 class="mt">Is this the ideal way to do it?</h3><label for="demo-share">Who can borrow it?</label><select id="demo-share">${teamOptions(state.scope==='personal'?'':state.scope)}</select><div class="detail-actions"><button class="button" id="demo-approve">Yes, save this skill ↗</button><button class="button ghost" id="demo-not-yet">Not yet</button></div>`:`<p class="description mt">${captured.team_name?'Shared with '+esc(captured.team_name)+'. Your demo teammates can now borrow the method.':'Saved to your personal library. You can share it with a team anytime.'}</p><div class="detail-actions"><a class="button" data-route href="/app?skill=${captured.id}">Open saved skill ↗</a><a class="button secondary" data-route href="/app?view=connect">Try another method</a></div>`}</div>`}</div><aside class="demo-flow-notes"><p class="eyebrow">ONE METHOD. MORE REACH.</p><h2>The useful part travels.</h2><div class="demo-note"><span>01</span><div><h3>Capture the approach</h3><p>The agent turns useful work into a method you can inspect.</p></div></div><div class="demo-note"><span>02</span><div><h3>Your yes makes it a skill</h3><p>Choose personal or team visibility. You have the final say.</p></div></div><div class="demo-note"><span>03</span><div><h3>Give the team a head start</h3><p>Borrow approved methods from the library for the next task.</p></div></div><p class="small-note">This conversation is a browser demo. A live Codex connection will be available when accounts are enabled.</p></aside></div>`);
  document.querySelector('#demo-capture-form')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;await busy(form.querySelector('button'),async()=>{const s=await rpc('skill_create',{...Object.fromEntries(new FormData(form)),category:'Design',description:'A focused page design method, captured from an example Codex conversation.',source:'codex'});await refresh();go('/app?view=connect&capture='+s.id);});});
  document.querySelector('#demo-approve')?.addEventListener('click',event=>busy(event.currentTarget,async()=>{await rpc('skill_approve',{id:captured.id,team_id:document.querySelector('#demo-share').value});await refresh();demoCodexPage();toast('Saved. Your method is ready to borrow.');}));
  document.querySelector('#demo-not-yet')?.addEventListener('click',()=>{go('/app?view=drafts');toast('Kept as a private draft. Nothing shared.');});
}
function demoInviteTeam(team){
  openModal('Try inviting a teammate',`<p class="modal-description">Preview how someone joins ${esc(team.name)}. This demo invitation works only in this browser; it doesn’t send a message or add a real person.</p><form id="demo-invite-form"><label for="demo-person">Teammate’s display name</label><input id="demo-person" name="name" maxlength="100" value="Jordan Lee" required><div class="modal-actions"><button class="button" type="submit">Create demo invitation ↗</button></div></form>`);
  modal.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;await busy(form.querySelector('button'),async()=>{const name=new FormData(form).get('name');const invite=await rpc('invite_create',{team_id:team.id});const path='/demo?invite='+invite.token+'&name='+encodeURIComponent(name);openModal('An invitation to better work',`<p class="modal-description">Preview the joining experience, then add a simulated teammate to your demo team.</p><div class="invite-link">${esc(location.origin+path)}</div><div class="modal-actions"><button class="button" id="preview-demo-invite">Preview invitation ↗</button></div>`);document.querySelector('#preview-demo-invite').onclick=()=>go(path);});};
}
async function demoJoinPage(token){
  try{const invite=await rpc('invite_preview',{token});shell('team',`<p class="eyebrow">INVITATION PREVIEW</p><h1>A place on ${esc(invite.team_name)}.</h1><p class="description">See what joining feels like. Accepting adds a simulated teammate in this browser.</p><div class="panel mt"><form id="demo-join-form"><label for="join-name">Display name</label><input id="join-name" name="name" maxlength="100" required value="${esc(new URLSearchParams(location.search).get('name')||'Jordan Lee')}"><button class="button mt" type="submit">Join demo team ↗</button></form></div>`);document.querySelector('#demo-join-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;await busy(form.querySelector('button'),async()=>{await rpc('invite_accept',{token,name:new FormData(form).get('name')});state.scope=invite.team_id;await refresh();go('/app?view=team');toast('Demo teammate joined.');});};}catch(error){shell('team',`<div class="empty"><h2>Invitation unavailable.</h2><p>${esc(message(error))}</p><a class="button" data-route href="/app?view=team">Back to teams</a></div>`);}
}
function demoSettingsPage(){shell('settings',`<p class="eyebrow">MAKE YOURSELF AT HOME</p><h1>Your demo workspace.</h1><p class="description">Make it yours. Changes are saved on this browser.</p><div class="panel mt"><form id="demo-profile" class="settings-form"><label for="demo-name">Display name</label><input id="demo-name" name="name" value="${esc(state.data.profile.name)}" maxlength="100" required><button class="button" type="submit">Save changes</button></form></div><div class="panel"><h3>Start again anytime.</h3><p class="description">Use Reset demo above to restore the sample team and skills. No account, email, or password needed.</p></div>`);document.querySelector('#demo-profile').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;await busy(form.querySelector('button'),async()=>{await rpc('profile',{name:new FormData(form).get('name')});await refresh();demoSettingsPage();toast('Name updated.');});};}
async function route(){
  const version=++state.routeVersion,path=demoMode?'/app':location.pathname,query=new URLSearchParams(location.search);
  if(!client&&!demoMode)return;
  if(query.get('recovery')==='1'&&state.session){authPage('reset');return;}
  if(!state.session){if(path!=='/login'&&path!=='/signup'){history.replaceState({},'','/login?next='+encodeURIComponent(path+location.search));}authPage(location.pathname==='/signup'?'signup':'login');return;}
  if(path==='/login'||path==='/signup'){go(safeNext());return;}
  try{
    if(!state.data)await refresh();if(version!==state.routeVersion)return;
    if(demoMode&&query.has('invite')){await demoJoinPage(query.get('invite'));return;}
    if(path==='/join'){await joinPage();return;}
    if(path==='/authorize'){await authorizePage();return;}
    if(query.get('next')){go(safeNext());return;}
    if(query.has('workspace')){const scope=query.get('workspace');if(scope==='personal'||state.data.teams.some(t=>t.id===scope)){state.scope=scope;localStorage.setItem(demoMode?'lattice-demo-scope':'lattice-scope',scope);}else{shell('tree','<div class="empty"><h2>Workspace unavailable.</h2><p>Select one of your workspaces to explore its skills.</p></div>');return;}}
    if(query.has('skill')){skillDetail(query.get('skill'));return;}
    switch(query.get('view')){case 'tree':workspaceTreePage();break;case 'team':await teamsPage(version);break;case 'connect':connectPage();break;case 'settings':settingsPage();break;case 'drafts':library(true);break;default:library();}
  }catch(error){root.innerHTML=`<div class="center-page">${brand}<div class="join-card"><h2>Couldn’t open your workspace.</h2><p class="description">${esc(message(error))}</p><button class="button mt" id="retry">Try again</button><button class="text-button" id="error-logout">Log out</button></div></div>`;document.querySelector('#retry').onclick=()=>{state.data=null;route();};document.querySelector('#error-logout').onclick=async()=>{await client.auth.signOut();state.session=null;go('/login');};}
}
async function start(){if(demoMode){demoStore=createDemoStore();state.session={user:{id:demoStore.userId}};state.scope=localStorage.getItem('lattice-demo-scope')||demoStore.defaultTeam;await refresh();await route();return;}try{const response=await fetch('/api/config');const config=await response.json();if(!response.ok||(config.provider!=='neon'&&(!config.url||!config.key)))throw new Error('The account service is not configured yet. Please try again shortly.');emailAuthReady=config.emailAuthReady!==false;authProvider=config.provider||'supabase';client=authProvider==='neon'?createNeonClient():createClient(config.url,config.key,{auth:{detectSessionInUrl:true,persistSession:true,autoRefreshToken:true}});const {data:{session}}=await client.auth.getSession();state.session=session;client.auth.onAuthStateChange((event,session)=>{const previousUser=state.session?.user.id;state.session=session;if(event==='PASSWORD_RECOVERY')setTimeout(()=>authPage('reset'),0);if(event==='SIGNED_OUT'||(previousUser&&previousUser!==session?.user.id)){state.data=null;state.routeVersion++;closeModal();root.replaceChildren();setTimeout(()=>route(),0);}});await route();}catch(error){authLayout(`<h2>We’re setting things up.</h2><p class="description">${esc(message(error))}</p><a class="button mt" href="/">Back to Lattice</a>`);}}
start();
